const item=$input.first().json;
item.retry_count=(item.retry_count||0)+1;
if(item.retry_count>3)throw new Error('Max retries');
return [{json:item}];

const msg=($input.first().json.message||'').toLowerCase();
let intent='general';
if(msg.includes('alert')||msg.includes('cảnh báo'))intent='alerts';
else if(msg.includes('threat')||msg.includes('đe dọa'))intent='threats';
else if(msg.includes('ip')||msg.includes('block'))intent='firewall';
else if(msg.includes('risk')||msg.includes('rủi ro'))intent='risk';
else if(msg.includes('visitor')||msg.includes('truy cập'))intent='visitors';
const item=$input.first().json;
item.intent=intent;
return [{json:item}];

const item=$input.first().json;
const msg=item.message||'';
let reply='Xin chào! Tôi là RiceGuard AI.';
if(item.intent==='alerts') reply='Hiện có '+ (item.total||0)+' cảnh báo, '+ (item.new_count||0)+' chưa xử lý, '+(item.critical||0)+' mức critical.';
else if(item.intent==='threats') reply='Có '+(item.total||0)+' mối đe dọa, '+(item.blocked||0)+' IP đã bị chặn.';
else if(item.intent==='firewall') reply='Hệ thống đã chặn '+(item.blocked_ips||0)+' IP.';
else if(item.intent==='risk') reply='Mức rủi ro: '+(item.critical_open||0)+' cảnh báo critical chưa giải quyết.';
else reply='Tôi có thể giúp bạn về cảnh báo, mối đe dọa, IP bị chặn, và rủi ro hệ thống.';
return [{json:{reply,timestamp:new Date().toISOString(),intent:item.intent}}];
